    "Điểm Mạnh": "Em nghĩ điểm mạnh nhất của mình là khả năng tự học và sự tò mò. Khi gặp một thứ mình chưa biết, phản ứng đầu tiên của em thường không phải là bỏ qua mà là muốn tìm hiểu xem nó hoạt động như thế nào. Ví dụ gần đây em bắt đầu tự học Python, và em nhận ra mình khá thích quá trình từ không hiểu gì đến khi tự giải thích được vấn đề. Em nghĩ điều này khá phù hợp với môi trường của một CLB IT, vì em không kỳ vọng mình đã giỏi sẵn, nhưng em tin mình là người có thể học nhanh và liên tục cải thiện khi được đặt trong một môi trường tốt..",
    "Điểm Yếu": "Điểm yếu của em là đôi khi em có xu hướng muốn hiểu khá kỹ trước khi bắt đầu làm. Điều đó giúp em không học một cách máy móc, nhưng đôi khi cũng khiến em mất nhiều thời gian để bắt đầu. Gần đây em đang cố thay đổi bằng cách áp dụng nguyên tắc: hiểu đủ để bắt đầu, sau đó vừa làm vừa sửa. Em nghĩ nếu tham gia CLB, việc được làm dự án và làm việc cùng mọi người sẽ giúp em cải thiện điểm này nhanh hơn.",
