    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến ITPTIT qua Fanpage của CLB khi tìm hiểu các CLB dành cho sinh viên CNTT tại PTIT",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Em biết ITPTIT là CLB trực thuộc Khoa CNTT1, có định hướng học thuật khá rõ, đặc biệt là lộ trình training từ C++ cơ bản đến thuật toán. Ngoài ra, em khá ấn tượng với tinh thần “Mãi là anh em” của CLB.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn có một môi trường để bắt đầu học lập trình một cách bài bản, rèn luyện tư duy và kỷ luật, đồng thời được học hỏi từ các anh chị và những người bạn có cùng định hướng.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em chưa dám nói mình có thể đóng góp điều gì quá lớn ngay từ đầu, nhưng em sẵn sàng học hỏi, chủ động nhận việc và có trách nhiệm với những việc mình được giao. Khi có thêm năng lực và kinh nghiệm, em muốn đóng góp nhiều hơn cho các hoạt động và dự án của CLB",
