    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Mình sẽ chủ động tham gia đầy đủ các hoạt động của CLB, hoàn thành tốt những nhiệm vụ được giao và đóng góp những ý tưởng mới. Bên cạnh đó, em muốn phát huy khả năng của bản thân để hỗ trợ các thành viên khác, cùng mọi người xây dựng một môi trường đoàn kết, năng động và ngày càng phát triển",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Mình đã tìm hiểu và biết rằng Mạng máy tính và Truyền thông dữ liệu chủ yếu liên quan đến việc thiết kế, xây dựng, quản lý hệ thống mạng và quá trình truyền, trao đổi dữ liệu giữa các thiết bị. Ngành cũng có thể phát triển sang các lĩnh vực như quản trị hệ thống, cloud và an toàn thông tin. Mình chọn ngành này vì em thấy công nghệ mạng là nền tảng quan trọng của các hệ thống hiện đại và em muốn tìm hiểu sâu hơn về cách chúng hoạt động",
