    "Địa Chỉ Email": "hoainhunguyen20@gmail.com",
    "Số Điện Thoại": "983135961",
    "Điểm Mạnh": "Em là người có tinh thần trách nhiệm, nghiêm túc với những việc mình đã nhận và luôn cố gắng hoàn thành đến cùng. Em có khả năng tự học, chủ động tìm hiểu những điều mình chưa biết và khá kiên trì khi gặp vấn đề khó. Bên cạnh đó, em luôn sẵn sàng lắng nghe góp ý và học hỏi từ những người có kinh nghiệm hơ",
    "Điểm Yếu": "Điểm yếu của em là đôi khi còn thiếu tự tin khi phải thể hiện ý kiến trước nhiều người và chưa có nhiều kinh nghiệm thực tế trong lĩnh vực CNTT. Tuy nhiên, em đang chủ động cải thiện bằng cách học hỏi, tham gia các hoạt động tập thể và mạnh dạn thử sức với những điều mới thay vì chỉ đứng ngoài quan sát.",
    "Sở Thích": "Em thích tìm hiểu về công nghệ, khám phá những kiến thức và công cụ mới, nghe nhạc, xem phim và tham gia các hoạt động cùng bạn bè. Em đặc biệt thích những hoạt động giúp bản thân được học hỏi, làm việc nhóm và tạo ra một sản phẩm hoặc kết quả cụ thể.",
    "Tính Cách": "Em là người khá hòa đồng, thân thiện nhưng cũng có phần hướng nội khi mới tiếp xúc. Khi đã làm quen, em khá cởi mở và sẵn sàng trao đổi với mọi người. Em coi trọng tinh thần trách nhiệm, sự tôn trọng và khả năng phối hợp trong tập thể. Em cũng là người thích thử sức với những điều mới và không ngại bắt đầu từ con số 0 nếu đó là điều mình muốn học.",
    "Thành Tích": "Thành tích nổi bật nhất của em hiện tại là đã hoàn thành kỳ thi THPT và chính thức bước vào môi trường đại học. Dù chưa có quá nhiều thành tích lớn, em coi việc dám thử sức với những lĩnh vực mới và chủ động chuẩn bị cho chặng đường đại học là một bước tiến quan trọng của bản thân. Em mong muốn thời gian tới có thể tạo ra những thành tích đáng nhớ hơn thông qua việc học tập và hoạt động CLB.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Trước đây em chưa có nhiều cơ hội tham gia các CLB hoặc đoàn thể một cách chính thức. Vì vậy, em muốn bắt đầu từ môi trường đại học, đặc biệt là CLB IT PTIT, để rèn luyện kỹ năng làm việc nhóm, giao tiếp và có thêm trải nghiệm thực tế.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến CLB IT PTIT thông qua các kênh thông tin dành cho sinh viên PTIT và quá trình tìm hiểu về các hoạt động của trường. Em ấn tượng với môi trường năng động, định hướng công nghệ và cơ hội được học hỏi, kết nối với những bạn có cùng sở thích. Vì vậy, em muốn thử sức và trở thành một phần của CLB.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo em tìm hiểu, IT PTIT là CLB CNTT của Học viện Công nghệ Bưu chính Viễn thông, tập trung vào học thuật, lập trình và các hoạt động phát triển kỹ năng. Em ấn tượng với môi trường năng động, nơi các thành viên có thể học hỏi, làm việc nhóm và cùng phát triển trong lĩnh vực công nghệ.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn khi đến với IT PTIT có thể học hỏi thêm nhiều kiến thức về CNTT, đặc biệt là những kiến thức thực tế ngoài chương trình học. Em cũng muốn rèn luyện kỹ năng làm việc nhóm, giao tiếp và tư duy giải quyết vấn đề. Quan trọng hơn, em hy vọng được gặp gỡ những người có cùng đam mê, tích lũy thêm nhiều trải nghiệm và có thể đóng góp sức mình vào các hoạt động của CLB.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em nghĩ trước hết mình cần có trách nhiệm với những việc được giao, chủ động tham gia các hoạt động và hỗ trợ mọi người khi cần. Bên cạnh đó, em cũng muốn đóng góp những ý tưởng mới và học hỏi thêm từ các anh chị, các bạn. Em hy vọng có thể cùng mọi người tạo ra nhiều hoạt động ý nghĩa và góp một phần nhỏ để CLB ngày càng phát triển hơn.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em tìm hiểu và biết rằng Công nghệ thông tin (CNTT) là một ngành học rất rộng lớn và năng động. Nó không chỉ bó hẹp trong việc viết code hay lập trình phần mềm, mà còn kết hợp rất mạnh mẽ với truyền thông, thiết kế giao diện (UI/UX) và tối ưu hóa trải nghiệm người dùng. Bản thân em nhận thấy CNTT chính là công cụ nền tảng giúp hiện thực hóa các ý tưởng sáng tạo và truyền thông trong thời đại số.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em đã từng tìm hiểu cơ bản về Python, chủ yếu là các kiến thức như biến, kiểu dữ liệu, câu lệnh điều kiện và vòng lặp. Em chưa có nhiều kinh nghiệm thực tế nhưng khá hứng thú với lập trình và có tinh thần chủ động học hỏi, sẵn sàng tìm hiểu thêm để nâng cao kiến thức.",
    "Định Hướng Phát Triển": "Trong 1-2 năm tới, em muốn tập trung xây dựng nền tảng vững về CNTT, đặc biệt là lập trình và các kiến thức chuyên ngành. Em cũng muốn chủ động tham gia các hoạt động, dự án của CLB để tích lũy kinh nghiệm thực tế, rèn luyện kỹ năng làm việc nhóm và giao tiếp. Bên cạnh đó, em sẽ cố gắng học hỏi và tìm hiểu sâu hơn về những lĩnh vực phù hợp với bản thân để có định hướng rõ ràng hơn trong tương lai.",
    "Bạn Có Hứng Thú Với Mảng Design / Thiết Kế Không?": "Có",
    "Kinh Nghiệm Hoặc Sản Phẩm Design Đã Từng Làm?": "Em chưa có kinh nghiệm thiết kế ấn phẩm trước đây. Tuy nhiên, em có tinh thần chủ động học hỏi, sẵn sàng tự tìm hiểu và làm quen với các công cụ thiết kế từ cơ bản. Em cũng luôn sẵn sàng tiếp thu góp ý, chủ động trau dồi để cải thiện khả năng và đóng góp tốt hơn cho CLB.",
