    "Địa Chỉ Email": "hahoan11919@gmail.com",
    "Số Điện Thoại": "911281658",
    "Điểm Mạnh": "Em sở hữu tư duy tự học cao và khả năng kiên trì giải quyết vấn đề khi gặp những bài toán khó. Bên cạnh đó, em luôn có tinh thần trách nhiệm, chủ động kết nối và phối hợp tốt với đồng đội để hoàn thành công việc đúng tiến độ. Em luôn sẵn sàng lắng nghe các góp ý và học hỏi từ mọi người. Em cũng dễ dàng thích nghi với môi trường mới và luôn sẵn sàng học hỏi những kiến thức công nghệ hiện đại. Em cũng từng được đào tạo và thực hành về các ngôn ngữ lặp trình từ năm c3 nên e cũng có nền tẳng để nhanh chóng tiếp thu những kiến thức công nghệ hiện đại mới",
    "Điểm Yếu": "Đôi lúc em còn khá rụt rè và ngần ngại khi phải phát biểu hoặc giao tiếp trước đám đông, khiến em chưa thực sự tự tin khi trình bày ý tưởng của mình. Bên cạnh đó, vì ở cấp 3 chủ yếu tự học và rèn luyện cá nhân nên em chưa có nhiều kinh nghiệm cọ xát với các dự án thực tế quy mô lớn hay làm việc trong một tập thể chuyên sâu về CNTT. Em đang chủ động khắc phục điểm yếu giao tiếp bằng cách tích cực mở lòng, tham gia các hoạt động nhóm và rất mong muốn gia nhập ITPTIT để rèn luyện sự tự tin cũng như học hỏi quy trình làm việc chuyên nghiệp hơn",
    "Sở Thích": "Em có niềm đam mê lớn với việc tìm hiểu công nghệ, học lập trình và thử thách bản thân qua các bài toán logic. Ngoài giờ học, em thích tham gia chơi bóng đá để rèn luyện thể lực, chơi các tựa game chiến thuật cùng bạn bè và đọc sách để nâng cao tư duy",
    "Tính Cách": "Em là một người hòa đồng, thẳng thắn và luôn thể hiện sự chỉn chu, có trách nhiệm trong công việc, em cũng là môtk người vui tính là ít xảy ra xung đột với bạn bè . Trong các hoạt động chung, em thuộc tuýp người điềm tĩnh, biết lắng nghe, cầu thị và sẵn sàng tiếp thu những góp ý chân thành để hoàn thiện bản thân mỗi ngày.",
    "Thành Tích": "Trong suốt các năm học THPT chuyên. KHTN , em luôn giữ vững danh hiệu Học sinh xuất sắc với gpa luôn trên 9. và đã trúng tuyển vào PTIT đúng với mục tiêu đề ra. Bên cạnh học tập, em từng cùng đội tuyển của trường xuất sắc đạt giải Nhì (Á quân) tại giải bóng đá cấp THPT, giúp em rèn luyện tính kỷ luật và bản lĩnh thi đấu.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "\"Ở cấp 3, em từng tham gia sinh hoạt tại CLB Bóng đá của Trường THPT Chuyên KHTN (HSGS). Mặc dù chưa từng tham gia CLB chuyên môn về công nghệ, việc sinh hoạt trong một CLB thể thao của trường chuyên đã giúp em rèn luyện tính kỷ luật, khả năng làm việc nhóm và kỹ năng kết nối tập thể. Bước vào đại học, em mong muốn dành trọn 100% sự tập trung và nhiệt huyết để thử sức tại ITPTIT.\"",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến ITPTIT trước hết qua các bài đăng truyền thông rất ấn tượng trên Fanpage chính thức của CLB trên Fb trong đợt tuyển thành viên. Ngoài ra, qua các buổi tìm hiểu về trường và lời giới thiệu đầy tự hào từ các anh chị khóa trên cũng như bạn bè cùng khóa, em càng hiểu rõ hơn về uy tín của CLB. Những chia sẻ chân thực về môi trường học tập và sinh hoạt tại đây đã thôi thúc em phải nộp đơn đăng ký ngay.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "\"Theo em tìm hiểu, ITPTIT là câu lạc bộ học thuật chuyên môn hàng đầu thuộc Khoa CNTT1 của Học viện Công nghệ Bưu chính Viễn thông. CLB không chỉ là nơi quy tụ những sinh viên có niềm đam mê mãnh liệt với lập trình và công nghệ, mà còn là 'lò đào tạo' chất lượng qua các chương trình training bài bản, dự án thực tế và các kỳ thi lập trình lớn (như ICPC hay Olympic Tin học). Ngoài ra, ITPTIT còn sở hữu văn hóa gắn kết, năng động và luôn hỗ trợ lẫn nhau giữa các thế hệ thành viên.\"",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "\"Em mong muốn tìm kiếm một môi trường học thuật nghiêm túc, năng động để tiếp tục củng cố tư duy lập trình và nâng cao kỹ năng xử lý các bài toán công nghệ. Khi gia nhập ITPTIT, em hy vọng sẽ được tham gia các buổi training chuyên môn chất lượng, nhận sự định hướng, dẫn dắt từ các anh chị khóa trên giàu kinh nghiệm và cọ xát với các thử thách lập trình thực tế. Bên cạnh chuyên môn, em mong muốn thông qua các hoạt động chung của câu lạc bộ sẽ rèn luyện kỹ năng làm việc nhóm, nâng cao sự tự tin và kết nối được với những người bạn đồng hành cùng chí hướng trong suốt quãng đời đại học.\"",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Nếu may mắn trở thành một phần của ITPTIT, em cam kết sẽ chấp hành nghiêm túc mọi quy định, tham gia đầy đủ và nhiệt tình vào các buổi sinh hoạt, training cũng như sự kiện của CLB. Em sẵn sàng nhận mọi nhiệm vụ được giao và nỗ lực hoàn thành xuất sắc bằng nền tảng tự học cùng tinh thần trách nhiệm của mình. Ngoài ra, em sẽ mang tinh thần thể thao năng nổ, sự chủ động để góp phần xây dựng một tập thể ITPTIT đoàn kết, vững mạnh và đầy năng lượng",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Ngành học của em tập trung trang bị kiến thức nền tảng về khoa học máy tính, cấu trúc dữ liệu, thuật toán và quy trình phát triển phần mềm. Ngành này đòi hỏi tư duy logic cao, khả năng tự học và cập nhật công nghệ mới liên tục.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "C++ , pythong",
