    "Điểm Mạnh": "Điểm mạnh của mình thì chắc là ở việc mình có thể tự học và có tính kiên trì tốt cùng với khả năng quản lí, tự chủ thời gian bản thân cũng như năng lực giao tiếp, làm việc nhóm tốt và khả năng ứng biến khi gặp sự cố.",
    "Điểm Yếu": "Còn điểm yếu thì mình chưa thực sự tự tin trong việc đảm nhiệm làm lãnh đạo và ngoài ra khả năng sáng tạo của mình vẫn còn một số hạn chế. Vì vậy, mình luôn sẵn sàng học hỏi thêm từ mọi người xung quanh và thử sức ở những lĩnh vực mới này.",
    "Sở Thích": "Mình thích chơi điện tử, đi du lịch, trải nghiệm ẩm thực và kết thêm nhiều bạn mới.",
    "Tính Cách": "Bản thân mình là một người khá hòa nhã, hiền lành đôi khi có thể hơi trầm trong môi trường mới. Nhưng khi đã làm quen thì mình khá chủ động, cởi mở giao lưu với mọi người.",
    "Thành Tích": "Mình từng cùng đội tuyển lọt vào vòng chung kết đấu loại Robotic của cuộc thi FARC năm lớp 11 với vai trò là lập trình viên robot do đại học FPT tổ chức.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Mình từng nằm trong ban chuyên môn lập trình của CLB Robotic and Engineering of Le Quy Don (R.E.D)",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Khi đi nhập học ở trường mình đã được một anh khóa D24 giới thiệu vào CLB ITPTIT.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo những gì mình tìm hiểu được thì ITPTIT là một CLB dành cho những người đam mê và yêu thức lập trình với nhiều thành tựu nổi bật như gần đây là giải hạng 2 cho cuộc thi ICPC do Học viện Công nghệ Bưu chính Viễn thông tổ chức.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Ngoài việc mở rộng quan hệ, kết thêm nhiều bạn mới và thử thách bản thân với những lĩnh vực mà mình đang còn chưa tốt thì trong khoảng thời gian sắp tời cùng CLB mình mong muốn đc tiếp tục trau dồi, rèn luyện bản thân với mục tiêu trước mắt là học thêm được nhiều ngôn ngữ lập trình mới và có thể có được một tấm vé vào cuộc thi ICPC và mang về thành tự cho CLB.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Nếu có cơ hội trở thành một thành viên của CLB mình sẽ cố gắng rèn luyện, học hỏi tích cực tham gia các hoạt động của CLB tổ chức và với nền tảng lập trình có từ CLB cũ mình mong muốn có thể sử dụng kiến thức ấy để tiếp tục đóng góp cho ITPTIT.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Theo những gì mình tìm hiểu, khoa học máy tính là một nghành học tập trung vào thuật toán, cấu trúc dữ liệu, ngôn ngữ lập trình, kiến trúc máy tính và cơ sở dữ liệu với định hướng cho nhiều lĩnh vực chuyên sâu như trí tuệ nhân tạo (AI), máy học (Machine Learning), khoa học dữ liệu (Data Science), và phát triển phần mềm. Tuy nhân lực hiện giờ khá nhiều đòi hỏi tính cạnh tranh cao nhưng cơ hội việc làm vẫn vô cùng rộng mở cho những ai cố gắng phát triển, thử thách bản thân.",
