    "Điểm Mạnh": "Thông qua những project đã làm, em nhận thấy bản thân có tinh thần trách nhiệm cao và luôn cố gắng hoàn thành công việc đúng và thường trước thời hạn. Em không ngại tìm hiểu và học hỏi những kiến thức mới và luôn cố gắng tự phân tích, tìm hướng giải quyết khi gặp vấn đề. Khi cần tham khảo tài liệu hoặc nguồn bên ngoài, em ưu tiên hiểu bản chất vấn đề thay vì chỉ sao chép lời giải.",
    "Điểm Yếu": "Em có xu hướng dừng việc phát triển một sản phẩm khi đã đáp ứng được tiêu chí ban đầu, thay vì tiếp tục tối ưu hoặc mở rộng nó. Em nhận thấy mình còn nhiều thiếu sót đối với kiến thức chuyên ngành. Em cũng chưa có nhiều kinh nghiệm làm việc nhóm. Đây cũng là những điều em muốn cải thiện thông qua việc tham gia ITPTIT.",
    "Sở Thích": "Em rất thích chơi và coi game như là một hình thức nghệ thuật của riêng nó. Ngoài ra, em khá hứng thú với việc biến những ý tưởng bất chợt thành sản phẩm. Khi nghĩ ra một thứ gì đó mà mình thấy thú vị, dù lớn hay nhỏ, em thường muốn bắt tay vào làm thử ngay.",
    "Tính Cách": "Em khá hướng nội và thường không phải người chủ động bắt chuyện trong một môi trường mới. Tuy nhiên, khi đã làm quen và có cơ hội, em có thể cởi mở và hòa nhập với mọi người khá tốt.",
    "Thành Tích": "Em chưa có thành tích nổi bật trong lĩnh vực Tin học, nhưng em đã tự thực hiện một số project cá nhân mà mình khá tự hào, như: - Chương trình tạo ra mã QR. - Chương trình biến một tệp ảnh thành ASCII art. - Chương trình mô phỏng âm thanh bằng output của CAVA, cho phép tùy chỉnh phong cách hiển thị. - Cài và tùy biến giao diện của Arch Linux theo phong cách cá nhân. Ngoài ra, em đã đạt giải Ba HSG cấp thành phố Tiếng Anh (THPT) và 7.5 IELTS.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Đây là CLB đầu tiên của em.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết được hầu hết về CLB qua fanpage và web của CLB.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo những gì em thấy, ITPTIT là một CLB có môi trường học tập và làm việc năng động, chú trọng vào việc xây dựng sản phẩm và phát triển kỹ năng thực tế. Em đặc biệt ấn tượng với định hướng builder của CLB, vì điều này khá phù hợp với sở thích tự làm và thử nghiệm những ý tưởng của bản thân.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Khi trở thành thành viên ITPTIT, em mong muốn được tiếp cận với những project thực tế, học cách xây dựng các sản phẩm có quy mô lớn hơn những project cá nhân mà em từng thực hiện, đồng thời cải thiện khả năng làm việc nhóm cùng với kiến thức và kỹ năng backend.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em có thể đóng góp sự chủ động trong việc tìm hiểu những điều mới, tinh thần tự học và sự tò mò với công nghệ vào các project của CLB. Em cũng sẵn sàng chia sẻ những gì mình tìm hiểu được với các thành viên khác, đồng thời chủ động học hỏi từ mọi người để cùng hoàn thiện sản phẩm.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em đã cân nhắc giữa ngành Công nghệ thông tin với ngành Khoa học máy tính. Cả hai ngành đều có phạm vi khá rộng và phù hợp một người chưa xác định rõ vị trí hay stack cụ thể muốn theo đuổi. Nhưng khác với CNTT, KHMT tập trung sâu hơn về cách mọi thứ hoạt động đằng sau mọi hệ thống mà mình sử dụng thường ngày. Với em, nếu muốn build thì mình cần phải hiểu cách nó hoạt động. Ngoài ra, em cũng khá hứng thú với tính nerdy của lĩnh vực này và muốn được hòa nhập với cộng đồng có cùng sự tò mò về công nghệ.",
