    "Số Điện Thoại": "352364024",
    "Điểm Mạnh": "- Có tinh thần học hỏi, chủ động trong công việc và có trách nhiệm với nhiệm vụ được giao. - Hòa đồng, cởi mở, tích cực và có khả năng làm việc nhóm. - Có kinh nghiệm tham gia và tổ chức một số hoạt động, sự kiện cấp CLB. - Có nền tảng tốt về lập trình, thành thạo ngôn ngữ C++. - Có khả năng chơi một số môn thể thao như bóng đá, bóng chuyền và cầu lông.",
    "Điểm Yếu": "- Khả năng giao tiếp còn chưa tốt, đặc biệt là trong việc chủ động làm quen và kết nối với mọi người. - Kinh nghiệm làm việc trong môi trường chuyên nghiệp còn ít, cần tiếp tục học hỏi và trau dồi thêm. - Chưa thành thạo một số ngôn ngữ như Python, HTML, CSS.",
    "Sở Thích": "Em thích lập trình và đặc biệt hứng thú với lập trình thi đấu. Ngoài ra, em cũng yêu thích các môn thể thao như bóng đá, bóng chuyền và thường tham gia các hoạt động tập thể. Em cũng hứng thú với những hoạt động sôi nổi, nơi em có thể học hỏi thêm, rèn luyện bản thân và có cơ hội làm quen với nhiều người.",
    "Tính Cách": "Em là người khá hướng nội và đôi khi còn ngại phát biểu trước đám đông. Tuy nhiên, em lại thích tham gia các hoạt động tập thể, bởi em muốn bước ra khỏi vùng an toàn, cải thiện những điểm còn hạn chế và rèn luyện bản thân. Em cũng là người có tinh thần cầu tiến, luôn đặt mục tiêu cho bản thân và cố gắng hết sức để đạt được những kết quả tốt.",
    "Thành Tích": "- Lớp 10: Giải Nhì HSG Tin khối 10 cấp trường; Giải Nhì HSG Tin khối 12 cấp trường; HCB Trại hè Hùng Vương; Giải Khuyến khích DHBB; Chứng chỉ MOS Word. - Lớp 11: Giải Nhì HSG Tin khối 12 cấp trường; Giải Nhì HSG Tin khối 12 cấp tỉnh; HCB Trại hè Hùng Vương; Giải Khuyến khích DHBB; Giải Khuyến khích Olympic THPT của VNU. - Lớp 12: Giải Nhì HSG Tin khối 12 cấp trường; Giải Nhì HSG Tin khối 12 cấp tỉnh; Giải Khuyến khích Olympic THPT của VNU.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Trước đây ở cấp THPT, em từng tham gia: - CLB Tin học của trường THPT Chuyên Sơn La, hiện nay là CLB STEM Chuyên Sơn La. - Chương trình Tiếp sức mùa thi do CLB Tình nguyện Chuyên Sơn La tổ chức.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến CLB IT PTIT qua các bài truyền thông của CLB trên Facebook, qua bạn bè và đặc biệt là qua các hoạt động trực tiếp của CLB tại sự kiện chào đón tân sinh viên của PTIT.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo những gì em tìm hiểu, CLB IT PTIT là một CLB học thuật thuộc Khoa CNTT1, tập trung vào các lĩnh vực liên quan đến Công nghệ thông tin và đặc biệt là lập trình. CLB có nhiều hoạt động học thuật như chia sẻ kiến thức, rèn luyện Cấu trúc dữ liệu và Giải thuật, cũng như tạo cơ hội cho thành viên tham gia các cuộc thi như ICPC, Olympic Tin học, Hackathon,... Bên cạnh chuyên môn, CLB cũng chú trọng phát triển các kỹ năng mềm và tổ chức nhiều hoạt động gắn kết giữa các thành viên.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn có thể học hỏi thêm nhiều kiến thức chuyên môn từ các anh chị và các thành viên trong CLB, đặc biệt là về lập trình. Bên cạnh đó, em cũng muốn cải thiện và phát triển các kỹ năng mềm như giao tiếp, làm việc nhóm và tổ chức hoạt động.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em có nền tảng về C++, Cấu trúc dữ liệu và Giải thuật (DSA), lập trình thi đấu, cùng với kinh nghiệm tham gia và tổ chức các hoạt động CLB. Em mong muốn có thể đóng góp những kiến thức và kinh nghiệm của mình, đồng thời chủ động tham gia các hoạt động để cùng mọi người xây dựng và phát triển CLB.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Theo những gì em tìm hiểu, Công nghệ thông tin là một lĩnh vực khá rộng, bao gồm nhiều mảng như lập trình, cơ sở dữ liệu, mạng máy tính, an toàn thông tin, trí tuệ nhân tạo,... Trong đó, lập trình là một phần quan trọng, giúp xây dựng và phát triển các phần mềm, hệ thống để giải quyết những bài toán thực tế. Em cũng hiểu rằng ngành này không chỉ yêu cầu kiến thức chuyên môn mà còn cần tư duy logic, khả năng tự học và liên tục cập nhật kiến thức. Đây cũng là lý do em muốn tiếp tục phát triển niềm yêu thích với lập trình và tìm hiểu sâu hơn về lĩnh vực này trong những năm đại học.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em có nền tảng về ngôn ngữ C++, DSA và cũng có tìm hiểu qua về ngôn ngữ Python / HTML / CSS.",
    "Định Hướng Phát Triển": "Trong 1–2 năm tới, em muốn tiếp tục nâng cao năng lực lập trình, đặc biệt là C++ và Cấu trúc dữ liệu & Giải thuật để củng cố tư duy lập trình và khả năng giải quyết vấn đề. Bên cạnh đó, em muốn cải thiện Python, HTML, CSS và tìm hiểu thêm một số ngôn ngữ, công nghệ khác để mở rộng khả năng lập trình. Em cũng muốn tham gia các cuộc thi, thực hiện các dự án cá nhân và qua đó từng bước xác định hướng chuyên môn phù hợp để phát triển lâu dài.",
