    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến CLB IT PTIT thông qua Facebook và các kênh truyền thông của CLB.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo những gì em tìm hiểu, IT PTIT là một CLB hoạt động trong lĩnh vực Công nghệ thông tin với quy mô lớn, có nhiều ban/phòng ban được phân công rõ ràng. Em ấn tượng với môi trường hoạt động chuyên nghiệp của CLB cũng như các hoạt động giúp thành viên học hỏi, phát triển kỹ năng và kết nối với những người cùng đam mê công nghệ.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn được học hỏi thêm nhiều kiến thức và kỹ năng mới, đặc biệt là những kiến thức thực tế bên cạnh việc học trên trường. Em cũng mong có cơ hội gặp gỡ, làm việc cùng những người có chung sở thích và đam mê",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em sẽ cố gắng hoàn thành tốt những công việc được giao, chủ động học hỏi và không ngại tiếp thu những góp ý từ mọi người. Dù hiện tại em chưa có nhiều kinh nghiệm, em tin rằng với tinh thần trách nhiệm và sự cố gắng, em có thể từng bước đóng góp vào các hoạt động và sự phát triển của CLB.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Ngành khoa học máy tính của em sẽ là thiên về thu thập, xử lý dữ liệu hơn là lập trình thuần túy. Ngành cũng liên quan đến AI, cơ sở dữ liệu và thuật toán. Bản thân em cũng muốn học rộng trước khi xác định hướng chính của mình",
