    "Điểm Mạnh": "Điểm mạnh của em là tò mò, thích vọc vạch khám phá những điều mới.",
    "Điểm Yếu": "Do quá tò mò nên sẽ hay bị lan man khi học (theo kiểu cái gì cũng sẽ xem qua kể cả những thứ không thực sự quan trọng) gây chậm trễ trong nhiều công việc.",
    "Sở Thích": "Em có sở thích với những thứ yêu cầu logic như code, chơi cờ vua, sửa chữa đồ điện tử ví dụ như 1 chiếc máy tính hư.",
    "Tính Cách": "Khép kín, thu mình, không quá hoạt ngôn, nhưng luôn cố gắng làm đến cùng, đôi khi bị xem là cứng đầu nhưng vẫn cởi mở với í kiến của mọi người ạ.",
    "Thành Tích": "Thành tích nổi bật mà em đạt được là: - Giải khuyến khích học sinh giỏi cấp tỉnh môn tiếng anh năm lớp 12 và lớp 9.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Em từng tham gia CLB LeVanHuu Radio khi còn học ở cấp 3, em cũng đã thực hiện qua 1-2 dự án cho CLB nhưng không quá nhiệt huyết do em không thực sự quan tâm và yêu thích đến lĩnh vực media.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết câu lạc bộ mình khi tìm hiểu về các câu lạc bộ của PTIT trên Facebook, sau đó là ở gian của clb vào ngày nhập học.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo em biết, CLB ITPTIT là câu lạc bộ về IT có liên kết với khoa CNTT1 của trường. CLB là nơi các thành viên học hỏi, trao đổi kiến thức và giúp đỡ lẫn nhau. Đây là môi trường rất tốt để phát triển bản thân và trải nghiệm thêm nhiều điểu mới.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Khi đến với ITPTIT em muốn được trau dồi thêm kiến thức và nâng cao kỹ năng lập trình và ngành mình theo học. Bên cạnh đó là được giao lưu học hỏi với những anh chị và các bạn trong câu lạc bộ để học thêm những kĩ năng mềm và có những quan hệ tốt cho mạng lưới xã hội của mình.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Nếu may mắn được tham gia, em mong sẽ được đóng góp và hỗ trợ cùng với ban kĩ thuật duy trì những trang web, app và những hoạt động liên quan đến kĩ thuật của CLB và nếu có thế cũng sẽ là hỗ trợ và giúp đỡ những thanh viên khác trong CLB đặc biệt là vấn đề training.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Về ngành học, em đã tìm hiểu và tự học ( do em không được học môn tin ở trường) ngôn ngữ C (cơ bản), Javascript ngoài ra còn có HTML, CSS, Tailwind, Typescript, React, Git và Github. Em có thực hành và hoàn thiện 2 project hoàn chỉnh sau để em tự kiểm tra lại kiến thức sau quá trình em tự học. - Đây 2 dự án lập trình nhỏ nhỏ sau quá trình tự học mong anh chị xem qua:  + https://github.com/EthanVuno5/Task-Manager-Pro.git  + https://github.com/EthanVuno5/EthanVuno5-copying-Gamma.com-as-a-learning-project.git ( Dự án đã được em làm từ lâu có nhiều phần chưa hoàn thiện nhưng là thành phẩm em code tay hoàn toàn nhằm kiểm tra hết kiến thức mà em đã học được, và tự tay thiết kế (dự án 2 là do em copy lại của Gamma.com do em rất kém phần design ạ), em chỉ dùng AI duy nhất cho việc viết doc về dự án)",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em đã học qua ngôn ngữ C và Javascript",
