    "Điểm Mạnh": "Em là người ham học hỏi, có tinh thần trách nhiệm và luôn cố gắng hoàn thành tốt những công việc được giao. Em khá kiên trì khi tìm hiểu một vấn đề mới, sẵn sàng tiếp thu góp ý và học hỏi từ những người có kinh nghiệm. Bên cạnh đó, em có tinh thần làm việc nhóm, biết lắng nghe và phối hợp với mọi người để hoàn thành mục tiêu chung. Em cũng có sự yêu thích đối với công nghệ thông tin và mong muốn được phát triển bản thân trong lĩnh vực này.",
    "Điểm Yếu": "Điểm yếu của em là đôi khi còn thiếu tự tin khi trình bày ý kiến trước nhiều người và chưa có nhiều kinh nghiệm tham gia các hoạt động CLB. Để khắc phục, em đang cố gắng chủ động hơn trong giao tiếp, mạnh dạn chia sẻ ý kiến và rèn luyện cách sắp xếp thời gian hợp lý. Em tin rằng môi trường CLB sẽ giúp em có thêm cơ hội thực hành và cải thiện những điểm này.",
    "Sở Thích": "Em thích tìm hiểu công nghệ thông tin, khám phá những kiến thức mới và học hỏi những điều có thể áp dụng vào thực tế. Ngoài ra, em cũng thích xem phim, nghe nhạc và dành thời gian cho những hoạt động giúp bản thân thư giãn. Em đặc biệt hứng thú với những hoạt động có thể giúp em vừa học hỏi thêm kiến thức, vừa được giao lưu và làm việc cùng mọi người.",
    "Tính Cách": "Em là người khá hòa đồng, ham học hỏi và có tinh thần trách nhiệm. Khi làm việc cùng mọi người, em luôn cố gắng lắng nghe ý kiến của các thành viên và hoàn thành phần việc của mình. Em cũng là người khá kiên trì, không dễ bỏ cuộc khi gặp khó khăn. Tuy nhiên, đôi khi em còn hơi ít nói và chưa thực sự tự tin trong những môi trường mới. Em đang cố gắng chủ động hơn trong giao tiếp để có thể hòa nhập tốt và phát huy khả năng của mình.",
    "Thành Tích": "HSG Cấp Trường môn Toán và Tin học lớp 10, HSG Cấp Trường môn Toán và Vật Lí lớp 11, Giấy Chứng nhận tham gia dự án thiện nguyện Summer Campaign 2024 và Ơ! Tết 2025 của CLB FOYO trực thuộc Hội Chữ thập đỏ Tỉnh Nghệ An.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Em đã từng tham gia các CLB của trường THPT liên quan đến các lĩnh vực như Olympia, cầu lông và cờ vua. Ngoài ra em còn là thành viên của CLB thiện nguyện trực thuộc Hội Chữ thập đỏ Tỉnh Nghệ An.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến CLB IT PTIT thông qua Facebook",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo tìm hiểu của em, ITPTIT là CLB học thuật thuộc Khoa CNTT1 – Học viện Công nghệ Bưu chính Viễn thông, là môi trường dành cho những bạn yêu thích và muốn phát triển trong lĩnh vực công nghệ thông tin. CLB không chỉ tạo điều kiện để các thành viên học hỏi về lập trình, tư duy giải quyết vấn đề và các kiến thức chuyên môn, mà còn chú trọng rèn luyện kỹ năng làm việc nhóm, giao tiếp và thuyết trình. Em cũng được biết CLB có nhiều hoạt động học thuật, các cuộc thi lập trình và hoạt động gắn kết thành viên. Điều khiến em ấn tượng là CLB vừa tạo cơ hội phát triển chuyên môn, vừa xây dựng một môi trường học tập và hoạt động tập thể năng động.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Khi đến với ITPTIT, em mong muốn được học hỏi thêm những kiến thức và kỹ năng liên quan đến công nghệ thông tin, đặc biệt là những kiến thức có thể áp dụng vào thực tế. Em cũng muốn được làm quen với những người có cùng sở thích, học hỏi kinh nghiệm từ các anh chị và rèn luyện khả năng làm việc nhóm, giao tiếp. Bên cạnh đó, em hy vọng có thể từng bước xác định rõ hơn định hướng phát triển của bản thân trong lĩnh vực CNTT. Em mong rằng đây sẽ là một môi trường giúp em trưởng thành hơn, tự tin hơn và có thêm những trải nghiệm đáng nhớ.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em sẽ cố gắng hoàn thành tốt những nhiệm vụ được giao, chủ động học hỏi và tích cực tham gia các hoạt động chung của CLB. Dù chưa có nhiều kinh nghiệm, em sẵn sàng tiếp thu hướng dẫn, hỗ trợ các thành viên khác và đóng góp những ý tưởng phù hợp với khả năng của mình. Em cũng sẽ cố gắng rèn luyện thêm các kỹ năng cần thiết để có thể tham gia hiệu quả hơn vào các hoạt động học thuật, sự kiện và dự án của CLB. Em tin rằng sự nhiệt tình, tinh thần trách nhiệm và thái độ cầu tiến của mình sẽ giúp em đóng góp một phần tích cực vào sự phát triển chung của ITPTIT.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Qua tìm hiểu, em nhận thấy Công nghệ thông tin là một ngành rộng, không chỉ bao gồm lập trình mà còn có nhiều lĩnh vực như phát triển phần mềm, cơ sở dữ liệu, mạng máy tính, trí tuệ nhân tạo và an toàn thông tin. Để theo học ngành này, người học cần có tư duy logic, khả năng tự học, sự kiên trì và tinh thần cập nhật kiến thức liên tục. Hiện tại, em vẫn đang khám phá các lĩnh vực trong ngành, đặc biệt là lập trình và phát triển phần mềm. Em mong muốn thông qua việc học tập và tham gia ITPTIT, em có thể tích lũy thêm kiến thức, trải nghiệm thực tế và định hướng rõ hơn cho tương lai.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em đã từng tìm hiểu và học những kiến thức cơ bản về C++ và Python.",
    "Định Hướng Phát Triển": "Trong 1–2 năm tới, em muốn tập trung củng cố kiến thức C++ và Python. Em cũng muốn học thêm các ngôn ngữ lập trình khác và tìm hiểu thêm về các lĩnh vực như phát triển phần mềm, AI hoặc khoa học dữ liệu để xác định hướng đi phù hợp. Em mong muốn thông qua việc học tập và tham gia ITPTIT, em có thể nâng cao kỹ năng lập trình, tích lũy kinh nghiệm thực tế và xây dựng nền tảng tốt cho những năm học tiếp theo.",
