    "Tính Cách": "Em là người chủ động, kiên trì và có tinh thần trách nhiệm cao. Em luôn ham học hỏi, không ngại đối mặt với bài toán khó hay thử thách mới, đồng thời hòa đồng và sẵn sàng hỗ trợ đồng đội trong công việc chung.",
    "Thành Tích": "MOS Excel 2016, Kk hsg tỉnh Vật lý",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Không",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến CLB thông qua fanpage chính thức của ITPTIT trên Facebook, qua sự giới thiệu của các anh chị khóa trên và bài đăng trong các hội nhóm sinh viên PTIT.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Em biết ITPTIT là Câu lạc bộ Lập trình uy tín và lâu đời tại PTIT, nơi hội tụ những sinh viên có niềm đam mê lớn với công nghệ. CLB không chỉ có môi trường học thuật chuyên sâu, sở hữu nhiều thành tích cao trong các cuộc thi lập trình lớn mà còn nổi tiếng với khẩu hiệu \"ITPTIT - Mãi là anh em\" thể hiện tinh thần đoàn kết, gắn bó và luôn sẵn sàng hỗ trợ lẫn nhau giữa các thế hệ thành viên.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn được rèn luyện tư duy thuật toán, nâng cao kỹ năng lập trình thực chiến thông qua các buổi training và dự án thực tế. Bên cạnh đó, em hy vọng sẽ tìm được những người bạn, người anh chị cùng đam mê để học hỏi, kết nối và phát triển bản thân trong suốt 4-5 năm đại học.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em sẽ tham gia đầy đủ, đúng giờ các buổi sinh hoạt, training và đóng góp tích cực vào các dự án chung. Em sẵn sàng chia sẻ kiến thức, hỗ trợ các thành viên khác, đồng thời lan tỏa năng lượng tích cực và sự nhiệt huyết để cùng xây dựng một tập thể ITPTIT ngày càng vững mạnh.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em đã tìm hiểu và biết Khoa học máy tính là ngành nghiên cứu sâu về lý thuyết thông tin, thuật toán, cấu trúc dữ liệu và các nguyên lý cốt lõi của hệ thống máy tính. Ngành học này không chỉ dừng lại ở việc viết code hay phát triển phần mềm đơn thuần, mà tập trung vào việc nghiên cứu tư duy giải quyết vấn đề, tối ưu hóa thuật toán, trí tuệ nhân tạo (AI), học máy (Machine Learning) và xử lý dữ liệu lớn. Đây là ngành đòi hỏi nền tảng Toán học vững chắc, khả năng tư duy logic cao và tinh thần tự học, nghiên cứu không ngừng.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em đã tự học và nắm chắc cơ bản về C/C++ để luyện tư duy thuật toán và lập trình hướng đối tượng. Bên cạnh đó, em cũng có tìm hiểu sơ qua về Python/Java để phục vụ cho các bài toán xử lý dữ liệu và xây dựng ứng dụng cơ bản.",
    "Định Hướng Phát Triển": "Trong 1–2 năm tới, em muốn tập trung nâng cao tư duy thuật toán, cấu trúc dữ liệu và tham gia các cuộc thi lập trình (như Lập trình sinh viên / ICPC). Đồng thời, em sẽ học sâu về C++ hoặc Python để nắm chắc nền tảng, sau đó thử sức với phát triển phần mềm hoặc tìm hiểu các mảng công nghệ chuyên sâu như Trí tuệ nhân tạo (AI) / Học máy (Machine Learning).",
    "Bạn Có Hứng Thú Với Mảng Design / Thiết Kế Không?": "Chưa xác định",
