    "Điểm Mạnh": "Em là một người biết chủ động, sáng tạo, có tinh thần trách nhiệm và luôn sẵn sàng học hỏi. Em có khả năng làm việc nhóm, giao tiếp và thích biến ý tưởng thành những sản phẩm thực tế.",
    "Điểm Yếu": "Đôi khi em khá cầu toàn nên dành nhiều thời gian để hoàn thiện công việc. Tuy nhiên, mình đang học cách quản lý thời gian và ưu tiên những việc quan trọng hơn.",
    "Sở Thích": "Em yêu thích công nghệ, thiết kế, truyền thông, sáng tạo nội dung và tìm hiểu những điều mới. Đặc biệt, em thích tham gia các hoạt động tập thể và dự án có tính sáng tạo.",
    "Tính Cách": "Hòa đồng, nhiệt huyết, trách nhiệm và khá năng động. Em luôn cố gắng lắng nghe, tiếp thu góp ý và không ngại thử sức với những điều mới.",
    "Thành Tích": "Từng tích cực tham gia các hoạt động Đoàn, tình nguyện, truyền thông và các dự án học tập/sáng tạo; có kinh nghiệm xây dựng sản phẩm truyền thông và tham gia các dự án khoa học kỹ thuật. Điển hình như: Đạt giải Nhất, Nhì cuộc thi KHKT cấp tỉnh ba năm liên tiếp. Đạt giải Nhì cuộc thi Sáng tạothanh thiếu niên nhi đồng cấp tỉnh. Đạt giải khuyến khích cuộc thi khởi nghiệp. Đạt danh hiệu Đoàn viên xuất sắc, Đoàn viên tiêu biểu của trường trong 3 năm liên tiếp.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Em đã từng tham gia các hoạt động Đoàn, Chủ nhiệm CLB MC, CLB truyền thông Leader Ban Phát thanh (Broadcast), qua đó có thêm kinh nghiệm làm việc nhóm, truyền thông và tổ chức hoạt động.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến CLB qua Facebook và các hoạt động truyền thông của CLB. Những sản phẩm và hoạt động của CLB khiến em cảm thấy đây là một môi trường rất phù hợp để học hỏi và phát triển.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Em biết Club IT PTIT là một CLB dành cho những bạn yêu thích công nghệ, nơi thành viên có cơ hội học hỏi kiến thức, phát triển kỹ năng và cùng nhau thực hiện những dự án thực tế.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn được học hỏi thêm về công nghệ, rèn luyện kỹ năng và đặc biệt là được làm việc cùng những người có chung đam mê để tạo ra những sản phẩm có giá trị.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em sẽ chủ động học hỏi, hoàn thành tốt nhiệm vụ được giao và đóng góp khả năng sáng tạo, truyền thông, thiết kế cũng như tinh thần trách nhiệm để cùng CLB phát triển. Ngoài ra, em không chỉ muốn trở thành một thành viên của CLB, mà muốn trở thành người tạo ra giá trị cho CLB.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em đã tìm hiểu về CNTT, đặc biệt là lập trình, phát triển phần mềm và AI. Đây là lĩnh vực đòi hỏi tư duy logic, khả năng tự học và luôn cập nhật kiến thức mới.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em đã tìm hiểu cơ bản về Python, C++ và HTML/CSS, đồng thời đang muốn học sâu hơn về Python và phát triển web.",
    "Định Hướng Phát Triển": "Vài năm tới em muốn nắm vững nền tảng lập trình, phát triển một số dự án thực tế và định hướng tìm hiểu sâu hơn về AI/Data hoặc Web Development.",
