    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Ngành học của em là công nghệ thông tin, là ngành học sẽ khá khó và cần phải cập nhật liên tục theo xã hội hiện nay. Tuy là một ngành học nặng nhưng lại thu hút rất nhiều sinh viên theo học vì có suy nghĩ tương tai sẽ kiếm được việc làm, và cũng chính vì thế mà thị trường về công nghệ đang bị thừa các lập trình viên ở hạng trung và thiếu các nhân lực chủ chốt. Vì vậy em nghĩ khi đã chọn ngành này thì bản thân phải cố gắng học tập và tự thêm cho mình thật nhiều kỹ năng để khi ra trường sẽ có chỗ đứng trong xã hội",
