    "Số Điện Thoại": "346022136",
    "Điểm Mạnh": "Điểm mạnh của e là tinh thần học hỏi và dễ thích nghi với môi trường mới. Khá kiên trì, luôn giữ được thái độ nghiêm túc và có trách nhiệm khi làm việc, cũng khá cẩn thận. Thích làm việc nhóm, sẵn sàng lắng nghe ý kiến và thích được tìm hiểu những kiến thức mới đb là về cntt.",
    "Điểm Yếu": "Điểm yếu: bởi vì mới vào trường nên e chưa có nhiều kiến thức chuyên môn và kinh nghiệm thực tế về it, lập trình, chưa giỏi giao tiếp nên đôi khi thiếu tự tin khi đứng trước nhiều người. Bởi vậy nên e coi đây là những điểm mà e cần cải thiện, hy vọng có thể vào được clb để được học hỏi từ các ac để rèn luyện và khắc phục.",
    "Sở Thích": "Sở thích của em là nghe nhạc,xem phim, chụp ảnh và tham gia các hoạt động tập thể, đi chơi cùng bạn bè. Ngoài ra em còn thích xem các nội dung về công nghệ, chỉnh sửa ảnh/video và tìm hiểu những công cụ mới. Em cũng thích học hỏi từ những người có kinh nghiệm và thử sức với những điều mới.",
    "Tính Cách": "Em là người khá hòa đồng, thân thiện và dễ thích nghi với môi trường mới. Em có tinh thần trách nhiệm, nghiêm túc khi làm việc nhưng cũng luôn sẵn sàng lắng nghe và tiếp thu ý kiến từ mọi người. Bên cạnh đó, em khá tò mò, thích tìm hiểu những điều mới và không ngại thử sức với những việc mình chưa từng làm.Ban đầu có thể hơi ít nói khi chưa quen, nhưng khi đã hòa nhập thì em khá năng động và thoải mái trong giao tiếp.",
    "Thành Tích": "Á Khoa đầu vào trường Thpt Hoằng Hóa 4 Đạt 100HSA (chưa cao lắm ạ)",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "E từng tgia cái hoạt động hội trại hè của xã trong nhiều năm liền ( đầu tiên là với vai trò là thiếu nhi sau đó là đoàn viên thanh niên )",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "E được biết về CLB IT PTIT là nhờ các bài đăng của CLB khi em biết mình trúng tuyển vào trường.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo những gì e tìm hiểu thì IT PTIT là 1 CLB dành cho sv yêu thích và quan tâm đến các lĩnh vực về cntt của trường. CLB là nơi tạo điều kiện cho sinh viên học hỏi trau dồi và nâng cao các kiến thức chuyên môn và còn có nhiều hoạt động, dự án và cơ hội để rèn luyện. Khi đki vào CLB thì sẽ được học hỏi từ các ac khóa trên được học tập để được trở thành thành viên của CLB và đặc biệt là có sự giúp đỡ của các giảng viên có kiến thức chuyên môn.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn được học hỏi thêm về CNTT, làm quen với môi trường mới và học hỏi kinh nghiệm từ các anh chị. Đồng thời, em muốn rèn luyện kỹ năng làm việc nhóm, giao tiếp và có thêm những trải nghiệm trong thời gian đại học.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em sẽ chủ động tham gia các hoạt động của CLB, hoàn thành tốt những công việc được giao và hỗ trợ mọi người khi có thể. Em cũng sẽ tích cực học hỏi, đóng góp ý tưởng và cố gắng phát huy những điểm mạnh của bản thân để cùng các thành viên xây dựng CLB ngày càng phát triển.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "CNTT là một ngành khá rộng, gồm nhiều hướng như lập trình, phát triển phần mềm, cơ sở dữ liệu, mạng và an toàn thông tin.Em đang  muốn tìm hiểu thêm qua các dự án và hoạt động thực tế để biết mình phù hợp với hướng nào.",
