    "Điểm Yếu": "Điểm yếu của mình là đôi khi hơi cầu toàn nên có thể dành nhiều thời gian cho một công việc. Khi mới bước vào môi trường mới, mình cũng chưa thực sự chủ động giao tiếp. Mình đang cố gắng cải thiện bằng cách quản lý thời gian tốt hơn và chủ động trao đổi với mọi người.",
    "Sở Thích": "Mình thích tìm hiểu về công nghệ và những kiến thức mới liên quan đến CNTT, đặc biệt là lập trình. Ngoài thời gian học tập, mình thích chơi game, nghe nhạc và tập thể thao để thư giãn.",
    "Tính Cách": "Mình là người khá hòa đồng, thân thiện và có tinh thần cầu tiến. Khi mới làm quen, mình có thể hơi ít nói nhưng sau khi quen sẽ cởi mở và dễ trao đổi hơn. Trong công việc, mình nghiêm túc, có trách nhiệm và luôn cố gắng tiếp thu góp ý để hoàn thiện bản thân.",
    "Thành Tích": "Mình đạt IELTS 6.0, SAT 1220 và có chứng chỉ MOS",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Trước đây mình chưa có nhiều kinh nghiệm tham gia các CLB chuyên môn. Mình chủ yếu tham gia các hoạt động tập thể của trường và lớp. Vì vậy, mình muốn thử sức trong một môi trường CLB tại đại học để có thêm kinh nghiệm làm việc nhóm, giao tiếp và tổ chức hoạt động.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Mình biết đến PTIT qua sự giới thiệu từ một đàn anh khóa trên",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo những gì mình tìm hiểu, IT PTIT là CLB dành cho những sinh viên có niềm yêu thích và định hướng phát triển trong lĩnh vực CNTT. CLB không chỉ tạo cơ hội học hỏi kiến thức chuyên môn mà còn giúp thành viên rèn luyện kỹ năng làm việc nhóm, giao tiếp và tham gia các hoạt động, dự án thực tế.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Mình mong muốn được học hỏi thêm kiến thức và kinh nghiệm về CNTT từ các anh chị và những người có cùng định hướng. Bên cạnh chuyên môn, mình muốn cải thiện kỹ năng giao tiếp, làm việc nhóm và khả năng tổ chức công việc. Mình cũng hy vọng có thể tham gia các dự án, hoạt động của CLB để tích lũy thêm kinh nghiệm thực tế.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Nếu có cơ hội trở thành thành viên, mình sẽ nghiêm túc hoàn thành những nhiệm vụ được giao và chủ động tham gia các hoạt động của CLB. Mình sẵn sàng đóng góp ý tưởng, hỗ trợ các thành viên khác và học hỏi những kỹ năng cần thiết. Mình muốn bắt đầu từ những công việc phù hợp với khả năng, sau đó không ngừng phát triển để có thể đóng góp nhiều hơn cho CLB.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Mình tìm hiểu rằng Công nghệ thông tin là lĩnh vực rộng, bao gồm lập trình, phát triển phần mềm, cơ sở dữ liệu, mạng máy tính, trí tuệ nhân tạo và an toàn thông tin. Đồng thời ngành yêu cầu khả năng tư duy logic, tự học và cập nhật kiến thức liên tục.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Mình đã có kiến thức cơ bản về HTML và cách xây dựng cấu trúc một trang web. Mình đã làm quen với các thẻ HTML cơ bản và cách tổ chức nội dung trên trang. Bên cạnh đó, mình cũng được trải nghiệm Python, chủ yếu ở mức làm quen với cú pháp, biến, vòng lặp, điều kiện và cách giải quyết các bài toán đơn giản",
    "Định Hướng Phát Triển": "Trong 1–2 năm tới, mình muốn xây dựng nền tảng lập trình vững chắc, đặc biệt về Python và C/C++. Sau đó, mình muốn tìm hiểu sâu hơn về phát triển phần mềm, thuật toán và các lĩnh vực CNTT phù hợp với bản thân. Mình cũng muốn tham gia các dự án nhỏ và hoạt động của CLB để có thêm kinh nghiệm thực tế.",
    "Bạn Có Hứng Thú Với Mảng Design / Thiết Kế Không?": "Chưa xác định",
