    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em muốn tìm một môi trường không chỉ giúp em củng cố kiến thức lập trình mà còn có cơ hội tham gia các dự án, cuộc thi và hoạt động thực tế. Bên cạnh việc hỏi từ các anh chị và các bạn, em mong muốn thử sức và đóng góp khả năng của mình và từng bước phát triển cả chuyên môn lẫn kĩ năng làm việc nhóm. Em tin rằng CLB sẽ là một môi trường phù hợp để khám phá rõ hơn định hướng của mình trong lĩnh vực khoa học máy tính",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Nếu trở thành một thành viên của CLB, em mong muốn đóng góp vào sự phát triển của CLB bằng những việc thiết thực nhất trong khả năng của mình. Trước hết, em sẽ chủ động học hỏi và tham gia đầy đủ các hoạt động của CLB để không ngừng nâng cao kiến thức cũng như kỹ năng của bản thân. Em tin rằng một thành viên phát triển tốt sẽ có thể đóng góp nhiều hơn cho tập thể. Bên cạnh đó, em sẵn sàng chia sẻ kiến thức, hỗ trợ những thành viên mới và cùng mọi người xây dựng một môi trường học tập tích cực, nơi mọi người có thể thoải mái trao đổi, giúp đỡ và cùng nhau tiến bộ. Ngoài ra, em cũng mong muốn đóng góp những ý tưởng mới cho các hoạt động, buổi training hoặc dự án của CLB. Em nghĩ rằng một CLB mạnh không chỉ đến từ những thành viên giỏi mà còn đến từ tinh thần chủ động, trách nhiệm và sự gắn kết giữa mọi người. Dù hiện tại kinh nghiệm của em vẫn còn hạn chế, nhưng em sẵn sàng học hỏi, chủ động nhận trách nhiệm và kiên trì đóng góp. Em hy vọng trong tương lai, mình không chỉ là người nhận được kiến thức từ CLB mà còn có thể trở thành một người tạo ra giá trị và góp phần giúp CLB phát triển mạnh hơn.",
