    "Điểm Mạnh": "- Hay tò mò, tìm hiểu và (có thể) vọc vạch những thứ mình thích - Hơi năng nổ, tìm hiểu, giao lưu và kết bạn với mọi người - Khá có trách nhiệm trong nhiệm vụ mình được giao - Hay giúp đỡ mọi người trong những việc mình có thể. - Chủ động và muốn học hỏi, lắng nghe và tiếp thu những ý kiến, phản hồi và kinh nghiệm của mọi người",
