    "Sở Thích": "- Tò mò và tìm hiểu về nhiều góc nghách của công nghệ (từ những sản phẩm đại chúng đến niche; lịch sử các công ty, người trong giới công nghệ; giai đoạn phát triển, nền tảng, kiến trúc các sản phẩm; sưu tầm và vọc vạch các món đồ công nghệ; hóng các sản phẩm cũng như các công nghệ tương lai; ...) - Thi thoảng mình edit video vui vẻ hoặc thử những thứ mới như edit ảnh, ... - Nghiền nghe EDM nước ngoài - Chơi game đua xe, xây thành phố, đá bóng - Xem F1 (thi thoảng), gần đây thêm Pokemon",
    "Tính Cách": "Mình hướng nội hoặc hướng ngoại tùy lúc; hơi hào phóng, sẵn sàng giúp đỡ người khác khi mình có thể; đôi khi lịch sử với mọi người hơi quá hoặc nói chuyện hơi tếu với những người mình thân quen; lúc thì nóng vội lúc thì quá chill; thi thoảng overreact; trí tưởng tượng phong phú nhưng đôi khi hơi quá \"bay bổng\"; tò mò và muốn tìm hiểu và tiếp thu những thứ mới.",
    "Thành Tích": "",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Mình biết đến khi tìm hiểu về các CLB của PTIT",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Là một trong những CLB lâu đời nhất của PTIT và là nơi phát triển các kỹ năng về lập trình cũng như kỹ năng mềm cho các thành viên",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Mình muốn nghiêm túc bước vào con đường lập trình (thực sự biết lập trình chứ không còn biết sơ qua, bề nổi nữa), được học hỏi và tiếp thu những kinh nghiệm từ những anh chị khóa trên cũng như các thầy cô, được phát triển những kỹ năng mềm, kỹ năng làm việc nhóm, kỹ năng làm dự án, khả năng sắp xếp thời gian, sẵn sàng cho những dự định tương lai của bản thân.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Khi mình đã bắt đầu có thể lập trình ổn rồi, mình sẽ tham gia các dự án của CLB cũng như có thể phần nào đó chia sẻ và truyền lửa cho các bạn mình cũng như các em lứa sau.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Mình đã có tìm hiểu qua về chương trình học cũng như là những khó khăn và học phí của ngành học mình rồi",
