    "Thành Tích": "Đạt giải khuyến khích cấp Thành phố Đấu trường Toán học Vioedu. 12 năm học sinh giỏi. Các giải Toán/Tin của Trường THPT nơi em theo học. Đạt 63,29 điểm Đánh gia Tư duy của Đại học Bách Khoa Hà Nội.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Hiện tại thì chưa tham gia CLB từ trước.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến từ page CLB IT PTIT trên nền tảng Facebook và các anh chị giới thiệu về CLB.",
