    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em muốn được huấn luyện các ngôn ngữ lập trình và các công nghệ mới. Mong muốn được cùng thành viên CLB tham gia những dự án để nâng cao trình độ và cùng nhau học hỏi, học tập những thành viên có cùng đam mê.",
