    "Điểm Mạnh": "Có tinh thần trách nhiệm, cố gắng hết sức có thể, nhiệt tình, sẵn sàng học hỏi, lắng nghe.",
    "Điểm Yếu": "Còn kém trong kĩ năng giao tiếp, chưa được sôi nổi, chủ động. Còn hơi lề mề, đôi lúc khá lơ ngơ, lầm lũi (làm trong im lặng).",
    "Sở Thích": "Thích được đi, được trải nghiệm. Về thể thao cầu lông là môn yêu thích của mình, mình còn thích nghịch bóng, nuôi cá, làm mấy đồ thủ công linh tính từ bìa, giấy, xem phim, nghe nhạc, đọc sách, truyện.",
    "Tính Cách": "Mình có chút hướng nội, nghĩ nhiều, khá cảm xúc, nhiều lúc có thể đi lang thang, quan sát một mình. Dù bản thân rất mong được kết nối, chia sẻ với mọi người nhưng mình lại không biết phải thể hiện thế nào qua lời nói (kiệm lời, chỉ biết lắng nghe rồi âm thầm). Mình còn hơi tự ti, hay ngại nên còn bị động, nhưng mình tin bản thân sẵn sàng cố gắng, giúp đỡ, hỗ trợ mọi người trong khả năng.",
    "Thành Tích": "Mình có từng đạt giải trong môn Văn ở cấp 2( không liên quan đến khoa học, công nghệ cho lắm😅). Mình học khối D, để thi vào ngành này mình có tự học thêm môn Tin, điểm của mình không cao, đó cũng không phải thành tích nổi bật nhưng mình cũng cảm ơn chính mình vì đã cố gắng, mình rất vui vì đỗ vào trường Ptit, có cơ hội được đổi mới, tiếp cận với công nghệ.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Năm cấp 3 mình có tham gia vào CLB phản biện của trường nhưng mình nói ấp úng quá nên chỉ đóng góp 1 số ý kiến thôi chứ không lên tranh luận.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Mình biết đến CLB qua các anh chị của trường giới thiệu trong ngày nhập học tại các gian hàng, tờ giới thiệu và mới đây là trong tuần lễ công dân.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "IT PTIT là CLB thuộc khoa CNTT1 của trường. CLB chia làm 2 khối là đào tạo và sự kiện. Khối đào tạo thì nghiêng về học thuật (lập trình, thuật toán, tham gia các cuộc thi, dự án). Khối sự kiện lại tập trung phát triển kỹ năng mềm, kỹ năng XH khi được tự mình tổ chức các sự kiện, hoạt động, giao lưu). Mình xin lỗi vì không nhớ, cũng chưa tìm hiểu CLB thành lập năm nào, có những thành tựu gì.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Mình mong muốn được học hỏi, trau dồi thêm kiến thức về lập trình,  gặp gỡ mọi người, biết đến những ý tưởng mới, sáng tạo, được tham gia vào các dự án về ứng dụng AI trong cuộc sống, giải quyết những khó khăn về môi trường, an toàn,...",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Trước hết mình sẽ cố gắng thay đổi để bản thân tích cực hơn, chủ động hơn, sẵn sàng, không ngại khi được giao nhiệm vụ, làm việc cùng mọi người. Tiếp đó là hết mình trong các cuộc thi, có ý tưởng cho những giải pháp.",
