    "Thành Tích": "Thành tích về tin học thì mình chưa có, nhưng mình học khá tốt tiếng anh (7.0 ielts).",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Mình từng tham gia khá nhiều CLB ở trường C3.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Mình biết đến CLB khi đi nhập học tại PTIT thông qua các anh chị cộng tác viên.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "ITPTIT là CLB chuyên môn về công nghệ thông tin trực thuộc khoa CNTT1. Đây là nơi trau dồi và rèn luyện tư duy về ngành cũng như là nơi giao lưu, kết nối với các anh/chị và các bạn cùng đam mê. Khi tham gia CLB mình sẽ được hỗ trợ, training về code như C, C++, và là nơi lập team để thi ICPC.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Mình muốn được trải nghiệm và học tập trong một môi trường năng động và chuyên nghiệp như của ITPTIT, để qua đó mà trau dồi bản thân, cũng như kết nối với nhiều người bạn cùng ngành hơn.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Khi tham gia ITPTIT, mình sẽ cố gắng phát triển CLB thông qua việc hỗ trợ và cải thiện các phần công việc CLB, cũng như là đẩy mạnh truyền thông bằng cách tuyên truyền, quảng cáo.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Ngành mà mình theo học là Khoa học máy tính. Đây là ngành học khá toàn diện về công nghệ thông tin, bao gồm các mảng như ATTT, Lập trình ứng dụng, Cloud, và chủ yếu là Dữ liệu, sau cùng là AI",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Mình đang học C, và từng học qua C++",
    "Định Hướng Phát Triển": "Mình muốn bản thân có thể sử dụng nhiều ngôn ngữ lập trình như: C, C++, Python,....Qua đó mà có thể tự tạo cho mình các project theo ý tưởng của bản thân",
