    "Sở Thích": "Từ khi học cấp 3, em đã có sở thích với máy tính và lập trình làm game. Còn ngoài đó ra thì em cũng thích chơi trò chơi điện tử và thể thao nữa.",
    "Tính Cách": "Em là 1 người hòa đồng, hoạt bát và có trách nhiệm với công việc của mình. Trong công việc hay học tập, em luôn cố gắng hoàn thành đúng thời hạn. Em biết là bản thân em vẫn chưa có nhiều kinh nghiệm nhưng em sẽ luôn tận tâm và cố gắng với công việc được giao, em mong muốn có thể học hỏi và nỗ lực tìm tòi với CLB mình.",
