    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "fanpage facebook và quẩy của CLB trong ngày nhập học",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo em, CLB ITPTIT là môi trường có những người có sở thích và đam mê về lập trình, đồng thời là 1 cộng đồng chia sẻ và cùng phát triển. Ngoài ra em cũng biết được CLB mình cũng có những hoạt động khá sôi nổi như các buổi training code, làm các dự án và cuộc thi ICPC.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "em mong muốn có thể xây dựng được cho bản thân một nền tảng vững chắc về CNTT và đồng thời có thể xác định rõ hơn về lĩnh vực mình yêu thích. Ngoài ra, em cũng mong muốn được tham gia những dự án, cuộc thi của CLB để phát triển mạnh hơn về khả năng của bản thân rồi từ đó có thể ổn định hơn trong và sau khi ra trường. Em hy vọng quãng thời gian đại học không chỉ giúp em có thêm những kiến thức và trải nghiệm mới về lĩnh vực, mà còn giúp em trở thành một người hòa đồng, có trách nhiệm và ham học hỏi hơn với CLB mình.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Trước hết, em sẽ đóng góp sự chủ động và trách nhiệm của bản thân. Em cam kết tham gia đầy đủ các buổi sinh hoạt, quỹ CLB, hoàn thành đúng hạn các nhiệm vụ được giao và không ngại nhận những công việc nhỏ nhất. Em cũng sẽ chủ động nâng cao chuyên môn của bản thân để có thể hỗ trợ những dự án của CLB đồng thời đóng góp những góc nhìn, ý tưởng mới cho các sự kiện của CLB.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em tìm hiểu thì thấy ngành CNTT mấy năm đầu chủ yếu tập trung tư duy qua mấy môn như giải thuật hay cấu trúc dữ liệu chứ chưa vào làm chuyên ngành ngay. Ngoài ra em cũng biết rằng ngành có những hướng như Web, Mobile, AI hay Data nên em cũng đang tranh thủ tìm hiểu để chọn mảng phù hợp. Em muốn vào CLB IT sớm cũng vì muốn có môi trường thực hành luôn những cái mình học chứ không chỉ dừng ở lý thuyết trên lớp.",
