    "Địa Chỉ Email": "Manhcuongle2707@gmail.com",
    "Số Điện Thoại": "345246397",
    "Điểm Mạnh": "Mình là người năng động, một khi thích điều gì đó là liên tục tìm tòi, khám phá đủ thứ và tận gốc rễ. Mình có tính kiên trì đặc biệt rất là lì, không chịu bỏ cuộc nếu vẫn biết có một điểm hy vọng nào đó. Mình rất thoải mái, đặc biệt với người thoải mái với mình.",
    "Điểm Yếu": "Điểm yếu là khả năng bình tĩnh, mình có thể làm nhiều thứ, những bài code giới hạn thời gian sẽ rất oke nếu mình cải thiện được điều này.",
    "Sở Thích": "Mình thích học, mình thích cảm giác mình làm chủ được điều gí đó, là kiến thức, là bài tập mà mình có thể xử lý bằng idea riêng của bản thân. Bên cạnh đó mình còn thích hát và chơi nhạc cụ.",
    "Tính Cách": "Năng động- thích tìm tòi những cái mới, những thứ mình thật sự hứng thú( ở đây là lập trình). Đôi khi mình còn là người khá kỹ tính, làm việc đó.",
    "Thành Tích": "Mình từng đạt trong top 10 học sinh có điểm thi vào 10 của trường, học sinh giỏi môn hoá học và điểm 9 toán năm 2025=)))",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Mình từng tham gia clb Podcast-PTIT thuộc ban truyền thông đa phương tiện",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Mình biết qua một người bạn và trên mạng xã hội",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo mình tìm hiểu, thì IT PTIT là clb chuyên về tập trung và đào tạo lập trình, phát triển kỹ năng cho sinh viên. Tất nhiên trong clb sẽ có lộ trình training từ C/C++, hay DSA và cả làm những project về mảng CNTT. Hiện tại mình đang học theo C++ và DSA nên mình thấy những định hương sủa clb khá phù hợp với bản thân mình. Mình muốn tham gia để có cơ hội học hỏi, rèn luyện và tìm hiểu sâu hơn về lập trình, cũng như mở rộng mối quan hệ trong ngành CNTT.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Điều mình mong muốn nhất khi đến với IT PTIT là có một môi trường để mình phát triển bản thân, đặc biệt là về lập trình và các kiến thức về CNTT. Mình muốn được học hỏi thêm từ các anh chị và các bạn, đồng thời có cơ hội tham gia các hoạt động, dự án thực tế để áp dụng những gì mình đã học. Bên cạnh đó, mình cũng muốn rèn luyện khả năng làm việc nhóm, giao tiếp và trở nên chủ động hơn. Mình hy vọng không chỉ nhận được kiến thức từ CLB mà mình cũng có thể đóng góp được một phần cho IT PTIT.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "mình sẽ cố gắng hoàn thành tốt những công việc được giao và tích cực tham gia các hoạt động của CLB. Mình cũng sẽ chủ động học hỏi để nâng cao chuyên môn, sau này khi có đủ kinh nghiệm thì mình muốn hỗ trợ lại các thành viên mới và đóng góp ý tưởng cho CLB. Mình nghĩ quan trọng nhất là có trách nhiệm với công việc và luôn sẵn sàng đóng góp khi CLB cần.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Ngành mình đang theo học bao gồm nhiều kiến thức về học thuật, công nghệ, nó đòi hỏi phải có tư duy về logic, toán học và thực chiến khá cao, công nghệ thì tiến bộ theo từng ngày và mình phải cố gắng bắt kịp, thậm chí còn phải chạy nhanh hơn nó.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Mình từng tìm hiểu qua C, C++ và Java",
    "Định Hướng Phát Triển": "Mình muốn thật là chắc nền tảng lập trình:C,C++,DSA… sau đó mình muốn chuyên sâu hơn về backend, frontend hay fullstack,…",
    "Bạn Có Hứng Thú Với Mảng Design / Thiết Kế Không?": "Có",
    "Kinh Nghiệm Hoặc Sản Phẩm Design Đã Từng Làm?": "Hiện tại mình chưa có",
