    "Điểm Mạnh": "Điểm mạnh của mình là khả năng tự học và sự kiên trì. Khi gặp một vấn đề chưa hiểu, mình thường không bỏ qua mà sẽ tìm cách tìm hiểu đến khi thực sự hiểu bản chất. Mình cũng khá chủ động trong việc học những thứ mới, đặc biệt là công nghệ và AI. Ngoài ra, mình luôn cố gắng hoàn thành những gì đã bắt đầu, kể cả khi quá trình đó không dễ dàng.",
    "Điểm Yếu": "Điểm yếu của mình là đôi khi hơi sa đà vào một vấn đề vì muốn hiểu thật rõ, dẫn đến việc mất nhiều thời gian hơn dự định. Mình đang cố gắng cải thiện điều này bằng cách xác định mức độ cần hiểu của từng vấn đề, ưu tiên việc hoàn thành công việc trước rồi mới đào sâu thêm khi có thời gian.",
    "Sở Thích": "Mình thích tìm hiểu về công nghệ, đặc biệt là AI, và tự học những thứ mới. Ngoài ra, mình thích nghe nhạc, chơi thể thao và đi đây đó để thay đổi không khí. Mình cũng khá thích những cuộc trò chuyện có chiều sâu, nơi mọi người có thể chia sẻ suy nghĩ và học hỏi lẫn nhau.",
    "Tính Cách": "Mình là người khá cởi mở, tò mò và thích tìm hiểu những điều mới. Khi đã quan tâm đến một vấn đề, mình thường muốn hiểu nó đến nơi đến chốn chứ không chỉ dừng ở việc biết sơ qua. Mình cũng khá thẳng thắn, có trách nhiệm với việc mình làm và luôn cố gắng giữ tinh thần cầu tiến. Tuy nhiên, mình vẫn đang học cách cân bằng giữa việc làm tốt một thứ và việc không để bản thân quá sa đà vào nó.",
    "Thành Tích": "Thành tích mình tự hào nhất hiện tại là đã duy trì được tinh thần tự học và chủ động tìm hiểu về AI, dù trước đó chưa có nhiều nền tảng về lĩnh vực này. Mình đang từng bước học thêm về lập trình, toán và các kiến thức nền tảng của AI. Mình biết đây mới chỉ là bước đầu, nhưng mình tin khả năng tự học và sự kiên trì sẽ giúp mình tiến bộ nếu có môi trường phù hợp.",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Trước đây mình chưa có nhiều kinh nghiệm tham gia các CLB. Tuy nhiên, mình muốn bắt đầu từ một môi trường nghiêm túc, có những người cùng đam mê và sẵn sàng học hỏi. Mình hy vọng có thể tích lũy kinh nghiệm, đóng góp khả năng của mình và phát triển hơn qua các hoạt động của CLB.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Mình được tìm hiểu thì đây là clb của khoa mình ạ",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Đây là CLB học thuật thuộc Khoa Công nghệ thông tin 1 – Học viện Công nghệ Bưu chính Viễn thông, không phải một CLB chỉ tổ chức hoạt động phong trào. CLB tập trung vào việc học tập, rèn luyện lập trình và phát triển cộng đồng sinh viên yêu CNTT.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Mình mong muốn tìm được một môi trường để học hỏi và phát triển nghiêm túc về CNTT, đặc biệt là AI. Hiện tại mình đang tự học và tìm hiểu khá nhiều thứ, nhưng đôi khi vẫn thiếu định hướng và một môi trường để cùng trao đổi, làm việc. Mình hy vọng khi đến với ITPTIT, mình có thể học hỏi từ các anh chị, được tiếp xúc với những bài toán và dự án thực tế, đồng thời có thêm động lực để biến những gì mình đang học thành năng lực thật sự. Mình cũng muốn tìm được những người có cùng đam mê để cùng nhau tiến bộ.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Mình nghĩ đóng góp không nhất thiết phải bắt đầu từ những việc quá lớn. Trước mắt, mình sẽ cố gắng hoàn thành tốt những công việc được giao, chủ động học hỏi để không trở thành người chỉ nhận sự giúp đỡ mà không tạo ra giá trị. Nếu có cơ hội, mình muốn tham gia vào các hoạt động học thuật, hỗ trợ chuẩn bị tài liệu, chia sẻ những gì mình tìm hiểu được và cùng mọi người giải quyết các vấn đề trong quá trình học tập. Mình cũng sẵn sàng làm những công việc phía sau để hoạt động của CLB diễn ra tốt hơn. Mục tiêu của mình là vừa phát triển bản thân, vừa trở thành một thành viên mà CLB có thể tin tưởng khi giao việc.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Ngành học này tập trung vào tư duy thuật toán, cấu trúc dữ liệu, lập trình phần mềm và xây dựng hệ thống. Em nhận thấy ngành đòi hỏi sự chủ động tự học rất cao, khả năng giải quyết vấn đề tốt và liên tục cập nhật công nghệ mới.",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "Em đã chủ động tìm hiểu và luyện tập với C++, Python và Java. Trong đó, em tập trung vào C++ để nắm vững tư duy lập trình căn bản, giải thuật và cấu trúc dữ liệu. Ngoài ra, em cũng tìm hiểu cơ bản về Python cho các bài toán xử lý dữ liệu/AI và Java cho lập trình hướng đối tượng.",
    "Định Hướng Phát Triển": "Trong 1–2 năm tới, mục tiêu của em là củng cố vững chắc nền tảng thuật toán, giải toán lập trình trên các trang như Codeforces/LeetCode và tham gia các cuộc thi lập trình sinh viên (như Kỳ thi Olympic Tin học hoặc ICPC). Song song đó, em muốn tìm hiểu sâu hơn về Trí tuệ nhân tạo (Machine Learning/Deep Learning) và hoàn thành một vài dự án cá nhân thực tế để tích lũy kinh nghiệm.",
    "Bạn Có Hứng Thú Với Mảng Design / Thiết Kế Không?": "Không",
