    "Tính Cách": "Em là một người khá hòa đồng, nhiệt huyết và luôn sẵn sàng trải nghiệm, học hỏi những điều mới. Dù đôi lúc còn hay suy nghĩ nhiều và thỉnh thoảng hơi ẩu, nhưng em luôn có ý thức tự nhìn nhận để sửa đổi, cố gắng hoàn thành tốt trách nhiệm được giao và rất dễ thích nghi khi làm việc trong một tập thể mới",
    "Thành Tích": "Hiện tại em chưa có thành tích học thuật nào quá lớn. Thành tích chủ yếu của em là thi đỗ vào ngành yêu thích và hoàn thành tốt vai trò ở CLB Thanh niên Tình nguyện cấp 3",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Em đã từng tham gia vào câu lạc bộ Thanh niên Tình nguyện ở cấp 3.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến ITPTIT qua ngày nhập học của trường.",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "ITPTIT là CLB trực thuộc Khoa CNTT1 của Học viện Công nghệ Bưu chính Viễn thông. CLB cũng có những phòng ban đảm nhiệm chức vụ đa dạng như là Truyền thông, Cơ bản, Thuật toán, Sự kiện, Tài chính. Trong đấy đối với em 2 phòng ban làm em hứng thú nhất là Cơ bản và Truyền thông.",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn được tiếp thu và học hỏi thêm nhiều kiến thức về lập trình, mở rộng mối quan hệ của bản thân, trau dồi thêm kĩ năng mềm và kinh nghiệm sống cũng như tạo kỉ niệm cho quãng đường đại học của bản thân.",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Nếu có thể vào CLB em sẽ cố gắng hết mình cho những hoạt động cũng như sự kiện của CLB, tích cực trao đổi và tương tác với các thành viên khác trong CLB.",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "CNTT là ngành liên quan đến sử dụng máy tính, phần mềm, sáng tạo phần mềm để bảo vệ, truyền thu thập thông tin phục vụ mọi người",
    "Bạn Có Hứng Thú Với Mảng IT / Công Nghệ Không?": "Có",
    "Kinh Nghiệm Hoặc Dự Án IT Đã Từng Làm?": "em có tìm hiểu một ít về C++. Cấp 3, em có được học Pascal",
    "Định Hướng Phát Triển": "em chưa có định hướng rõ ràng, em muốn trải nghiệm sau đó mới đưa ra quyết định ạ",
    "Bạn Có Hứng Thú Với Mảng Design / Thiết Kế Không?": "Chưa xác định",
