    "Tính Cách": "Tính cách cũng như điểm mạnh của em vậy . Em là một người khá cởi mở và dễ tính ạ đôi lúc hơi cáu bẩn xiu thuiii, em rất muốn học hỏi nên là em nói và hỏi ac khá nhiều ạ . Như hôm đi nhập học em ngồi vào bàn hỏi hết 3,4 ac liền :)",
    "Thành Tích": "Những thành tích nổi bật về văn hoá thì em chưa có nhưng em cũng có một vài thành tích về hoạt động toàn trường thoi ạ. Em không phải một người học giỏi nên khong được đi thi ạ",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Em lúc trước có tham gia clb văn nghệ của trường cấp 3 để em có thể cởi mở hơn và tự tin hơn khi nói chuyện ạ . Lúc đó trường em khá ít clb nên em vào clb văn nghệ và may mắn thay em cũng được làm đội trưởng ban ạ",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến clb của mình từ một anh chị cựu và em nghe loáng thoáng qua . Nhưng khi đi nhập học ngày đầu tiên của khoa cntt , em đã thấy ấn tượng với mọi người , em ngồi ở bàn tư vấn khá lâu , ngồi nghe anh thủ khoa và các chị đi trước chia sẻ em cảm thấy vui lắm khi mình đã dám đặt câu hỏi và được ac nhiệt tình trả lời ạ",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Về clb itptit em biết clb mình là clb trực thuộc khoa CNTT1 của Trường mình và là clb cho mọi người đam mê về lập trình và những thứ công nghệ số ạ",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn mình sẽ có thể thoát ra khỏi vùng an toàn của bản thân để đến với câu lạc bộ để có thể phát triển những kỹ năng lập trình và các kỹ năng mềm của bản thân ạ . Em có một ước mơ về cntt từ bé nhưng sau này mọi người bảo ngành này bão hoà lắm nhưng em tin rằng mình sẽ cố gắng vượt qua được và đầu tiên thì em muốn hiểu hơn về BA trước nên em cũng muốn được học hỏi từ các anh chị ạ",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Em sẽ cố gắng sắp xếp thời gian hợp lý nhất để có thể cân bằng được thời gian học của mình và với clb ạ , em hứa em sẽ hết mình vì clb mình để có thể cải thiện hơn ạ",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em học ngành CNTT chính quy nhưng em thật ra cũng không hẳn muốn mình là một người chỉ ngồi code nhưng em muốn CNTT là điểm tựa của mình để có thể theo một nghề nào đó có thể như BA . Em thích lãnh đạo và giao tiếp với mọi người nên em sẽ có thể k chịu được ngồi code hàng giờ trong nhiều năm ạ",
