    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Trước đây ở cấp 3 em từng tham gia một số câu lạc bộ học thuật như Vật Lý và Hoá Học, đây là lần đầu em thử sức với một bộ môn mới là IT , sẽ có khó khăn nhưng em mong được có cơ hội thử sức với CLB",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Qua các hoạt động và thông tin tuyển thành viên của CLB trên mạng xã hội",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Em biết IT PTIT là một CLB dành cho sinh viên yêu thích công nghệ, tạo môi trường để học hỏi, giao lưu và phát triển các kỹ năng liên quan đến IT. Em chưa có nhiều kiến thức chuyên môn về IT nhưng khá hứng thú và muốn được học hỏi thêm từ các anh chị và các bạn trong CLB",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em mong muốn có cơ hội làm quen với những người có cùng sở thích, được học hỏi thêm về công nghệ và những kỹ năng mới",
