    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Em có tìm hiểu về ngành Công nghệ Đa phương tiện và được biết đây là ngành kết hợp giữa công nghệ và sự sáng tạo, liên quan đến thiết kế đồ họa, chỉnh sửa hình ảnh,video, làm nội dung số, thiết kế web và các sản phẩm đa phương tiện",
