    "Mã Sinh Viên": "B26DCCE034",
    "Địa Chỉ Email": "ducbao556677@gmail.com",
    "Số Điện Thoại": "969604993",
    "Điểm Mạnh": "Về chuyên ngành thì em lên đại học mới bắt đầu tìm hiểu và làm quen về ngành mình đang học nên em không có điểm mạnh về ngành mình theo học mà là bắt đầu từ con số 0. Còn về những yếu tố khác thì em là 1 người khá hòa đồng thân thiện, biết lễ phép với bậc bề trên , biết lắng nghe ý kiến của những người đi trước và sửa sai Về khả năng tiếp thu kiến thức thì em thấy em tiếp thu 1 kiến thức mới ở mức khá ổn , điểm thi THPT vẫn còn dư nhiều so với ngành em theo học ạ , ở c3 em cũng thích những bài toán có tư duy logic .",
    "Điểm Yếu": "Em thì thấy bản thân là 1 người khá hay bị áp lực căng thẳng  có thể là về học tập ,thấy các bạn chăm chỉ đạt được các thành tích còn mình chưa thật sự nỗ lực để đạt được điều mình mong muốn, em cũng khá yếu phần kĩ năng mềm đặc biệt là khi giao tiếp hay phải thuyết trình trước đám đông hay khi phải giao tiếp , thuyết trình trước đám đông , khá rụt rè khi nói chuyện với các bạn nữ ạ.",
    "Sở Thích": "Hồi còn học cấp dưới thì em khá đam mê chơi rubik có thể dành nhiều tiếng trong ngày để ngồi ngẫm nghĩ cách giải , học video hướng dẫn nhưng gần cuối cấp thì việc học khá nhiều nên em không còn chơi nhiều nữa ạ nên em thấy mình cũng khá thích sự tư duy logic ạ . Còn về thể thao giải trí thì em thích chơi bóng chuyền ( mong đậu được CLB ITPTIT và CLB bóng chuyền) để vừa có những giây phút học tập nghiêm túc và giải trí để giải tỏa căng thẳng ạ",
    "Tính Cách": "Em là 1 người hòa đồng thân thiện , biết lắng nghe ý kiến của người khác và tiếp thu , ngoan ngoãn lễ phép với các anh chị khóa trên .Em rất tôn trọng những người giúp đỡ , chỉ bảo mình còn với những người có tính cách khá xấu thì không ạ.",
    "Thành Tích": "",
    "Kinh Nghiệm Hoạt Động Hoặc Làm Việc Đã Có?": "Em từng tham gia hoạt động múa hát của lớp ạ.",
    "Bạn Biết Đến Câu Lạc Bộ Qua Kênh Nào?": "Em biết đến từ khá nhiều nguồn, từ trên web liệt kê danh sách các CLB , từ các anh chị trong khoa CNTT1 , khi đến các gian CLB thì cũng được các thầy tư vấn còn đang không biết nhiều về ngành thì nên tham gia vào CLB IT PTIT ạ , còn thêm khi em đến trường được 1 anh tên Hưng cũng giới thiệu vào CLB ( bảo là ghi anh giới thiệu vào thì khả năng cao được duyệt vài đấy..)",
    "Bạn Hiểu Gì Về Câu Lạc Bộ?": "Theo em được biết thì CLB IT PTIT là đơn vị trực thuộc của khoa CNTT1 ,có thế mạnh trong ngành , khi tham gia được nhiều anh chị thầy cô giỏi giảng dạy đào tạo , có nhiều anh chị khóa trên rất giỏi đã có rất nhiều thành tích nổi bật .",
    "Mục Tiêu / Kỳ Vọng Của Bạn Khi Tham Gia CLB?": "Em khi lên đại học học ngành này còn như 1 tờ giấy trắng không biết gì về công nghệ , em mong muốn lên đại học có được 1 môi trường lành mạnh để rèn luyện bản thân cả về chuyên ngành học tập cũng như kĩ năng mềm , mong muốn được training trong 1 môi trường với nhiều người giỏi hơn mình được học tập và làm quen với những anh chị thầy cô và cũng mong muốn trong gần 5 năm học thì khi đó mình đã là một người thành thạo về code và có thể sẵn sàng đi xin việc bất cứ lúc nào.Em rất mong muốn bài viết này có thể được duyệt để em có thể được tham gia CLB IT PTIT ạ..",
    "Kế Hoạch / Định Hướng Đóng Góp Của Bạn Cho CLB?": "Vì ban đầu chuyên môn của em không cao nên em sẽ đóng góp cho CLB bằng chính sự kỉ luật quyết tâm của bản thân , sẽ tham gia đủ các buổi training của CLB 1 cách thật nghiêm túc và hoàn thành những gì được giao . Còn về sau giai đoạn nà , khi em đã có tính chuyên môn mức ổn thì em sẽ cố gắng cải thiện kĩ năng của bản thân để có thể cùng tham gia xây dựng các dự án sản phẩm cùng các anh chị thầy cô trong CLB ạ , đóng góp được nhiều nhất có thể để xây dựng nên 1 tập thể lành mạnh , có thể giúp ích được cho những người cần được hỗ trợ",
    "Kiến Thức Chuyên Môn Đã Có Về Ngành Học?": "Theo em thì ngành học phải dùng tư duy logic khá nhiều , học thêm các ngôn ngữ lập trình mới, và đặc biệt phải biết thêm về tiếng Anh thì mới có thể theo học được.",
